class Solution {
public:
    int maximumGap(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return 0;
        int lo = *min_element(nums.begin(), nums.end());
        int hi = *max_element(nums.begin(), nums.end());
        if (lo == hi) return 0;
        int bucketSize = max(1, (hi - lo) / (n - 1));
        int bucketCount = (hi - lo) / bucketSize + 1;
        vector<int> bucketMin(bucketCount, INT_MAX);
        vector<int> bucketMax(bucketCount, INT_MIN);
        for (int num : nums) {
            int idx = (num - lo) / bucketSize;
            if (num < bucketMin[idx]) bucketMin[idx] = num;
            if (num > bucketMax[idx]) bucketMax[idx] = num;
        }
        int maxGap = 0;
        int prevMax = bucketMax[0];
        for (int i = 1; i < bucketCount; i++) {
            if (bucketMin[i] == INT_MAX) continue;
            if (bucketMin[i] - prevMax > maxGap) maxGap = bucketMin[i] - prevMax;
            prevMax = bucketMax[i];
        }
        return maxGap;
    }
};
